cd /app && python3 - <<'PY'
p = 'src/index.ts'
s = open(p).read()

# imports
s = s.replace(
    "import { copy } from 'copy-anything';",
    "import { copy } from 'copy-anything';\nimport { ErrorClassRegistry } from './error-class-registry.js';\nimport type {\n  ErrorStackOptions,\n  NormalizedErrorStackOptions,\n} from './error-options.js';\nimport { normalizeErrorStackOptions } from './error-options.js';"
)

# constructor
old_constructor = """  constructor({
    dedupe = false,
  }: {
    dedupe?: boolean;
  } = {}) {
    this.dedupe = dedupe;
  }"""
new_constructor = """  constructor({
    dedupe = false,
    errorStack,
  }: {
    dedupe?: boolean;
    errorStack?: ErrorStackOptions;
  } = {}) {
    this.dedupe = dedupe;
    this.errorStackOptions = normalizeErrorStackOptions(errorStack);
  }"""
assert old_constructor in s
s = s.replace(old_constructor, new_constructor)

# add reset in serialize
old_serialize = """  serialize(object: SuperJSONValue): SuperJSONResult {
    const identities = new Map<any, any[][]>();"""
new_serialize = """  serialize(object: SuperJSONValue): SuperJSONResult {
    this.errorCauseDepthLeft = new WeakMap<Error, number>();
    const identities = new Map<any, any[][]>();"""
assert old_serialize in s
s = s.replace(old_serialize, new_serialize)

# add fields/methods after allowErrorProps
old_allowed = """  readonly allowedErrorProps: string[] = [];
  allowErrorProps(...props: string[]) {
    this.allowedErrorProps.push(...props);
  }"""
new_allowed = """  readonly allowedErrorProps: string[] = [];
  allowErrorProps(...props: string[]) {
    this.allowedErrorProps.push(...props);
  }

  readonly errorStackOptions: NormalizedErrorStackOptions | undefined;
  readonly errorStackClassRegistry = new ErrorClassRegistry();
  registerErrorStackProcessor(className: string, fn: (error: any) => any) {
    this.errorStackClassRegistry.register(className, fn);
  }

  private errorCauseDepthLeft = new WeakMap<Error, number>();

  getErrorCauseDepthLeft(error: Error, fallback: number): number {
    const stored = this.errorCauseDepthLeft.get(error);
    return stored === undefined ? fallback : stored;
  }

  setErrorCauseDepthLeft(error: Error, depth: number) {
    this.errorCauseDepthLeft.set(error, depth);
  }"""
assert old_allowed in s
s = s.replace(old_allowed, new_allowed)

# add static binding for registerErrorStackProcessor
old_static = """  static allowErrorProps = SuperJSON.defaultInstance.allowErrorProps.bind(
    SuperJSON.defaultInstance
  );"""
new_static = """  static allowErrorProps = SuperJSON.defaultInstance.allowErrorProps.bind(
    SuperJSON.defaultInstance
  );
  static registerErrorStackProcessor =
    SuperJSON.defaultInstance.registerErrorStackProcessor.bind(
      SuperJSON.defaultInstance
    );"""
assert old_static in s
s = s.replace(old_static, new_static)

# add named export
old_export = "export const allowErrorProps = SuperJSON.allowErrorProps;"
new_export = "export const allowErrorProps = SuperJSON.allowErrorProps;\nexport const registerErrorStackProcessor = SuperJSON.registerErrorStackProcessor;"
assert old_export in s
s = s.replace(old_export, new_export)

open(p, 'w').write(s)
print("index updated")
